RSpec.describe "Reservation locks seen through the entry API" do
  include_context "timekeeping entry writes"
  include_context "timekeeping entry writes without transactional fixtures"

  it "reports locked through the entry API exactly while a reservation exists and snapshots each flip" do
    company = timekeeping_arrange.company
    owner = timekeeping_arrange.user(company:, role: "owner")
    entry_id = timekeeping_arrange.entry(company:, user: owner, project: timekeeping_arrange.project(company:))
    service = timekeeping_arrange.service_identity(company:, name: "invoice-boundary",
                                                   operations: %w[prepare commit abort mark_billed detach_entries])
    operation_id = SecureRandom.uuid
    send_command = lambda do |route, extra = {}|
      body = { "invoice_id" => 501, "operation_id" => operation_id, "generation" => timekeeping_arrange.current_generation }
      post "/v1/companies/#{company}/reservations/#{route}", params: JSON.generate(body.merge(extra)),
                                                             headers: { "Content-Type" => "application/json", "Authorization" => "Bearer #{service}" }
      response
    end
    locked_in_api = lambda do
      get "/v1/companies/#{company}/entries/#{entry_id}",
          headers: { "Authorization" => "Bearer #{timekeeping_arrange.token_for(owner)}" }
      response.parsed_body.fetch("locked")
    end
    snapshots = -> { OutboxSnapshot.where(company_id: company, id: entry_id).order(:outbox_position).pluck(:locked) }

    # "From here on the entry API reports `locked: true` exactly when the entry has a reservation."
    expect(locked_in_api.call).to be(false)
    expect(send_command.call("prepare", "disposition" => "active", "entries" => [entry_id]).status).to eq(200)
    expect(locked_in_api.call).to be(true)
    # "Every reservation change that flips `locked` ... writes an audit row and an outbox snapshot row"
    expect(snapshots.call).to eq([true])
    expect(AuditEvent.where(company_id: company, entry_id:).count).to eq(1)

    expect(send_command.call("abort").parsed_body).to eq("dropped" => 1)
    expect(locked_in_api.call).to be(false)
    expect(snapshots.call).to eq([true, false])
    expect(AuditEvent.where(company_id: company, entry_id:).count).to eq(2)
  end
end

RSpec.describe "Detach-entries service command" do
  include_context "timekeeping entry writes"
  include_context "timekeeping entry writes without transactional fixtures"

  it "detaches the agent from the path company's entries with one audit and one snapshot row per entry" do
    company = timekeeping_arrange.company
    other_company = timekeeping_arrange.company
    employee = timekeeping_arrange.user(company:, role: "employee")
    project = timekeeping_arrange.project(company:)
    own = Array.new(2) { timekeeping_arrange.entry(company:, user: employee, project:, agent_id: 77) }
    foreign = timekeeping_arrange.entry(company: other_company, user: timekeeping_arrange.user(company: other_company, role: "employee"),
                                        project: timekeeping_arrange.project(company: other_company), agent_id: 77)
    service = timekeeping_arrange.service_identity(company:, name: "agent-destroy",
                                                   operations: %w[prepare commit abort mark_billed detach_entries])
    body = JSON.generate("operation_id" => SecureRandom.uuid, "generation" => timekeeping_arrange.current_generation)
    headers = { "Content-Type" => "application/json", "Authorization" => "Bearer #{service}" }

    # "Detach-entries nulls `agent_id` on that company's entries for the agent with one audit row per entry."
    post "/v1/companies/#{company}/agents/77/detach-entries", params: body, headers: headers

    expect([response.status, response.parsed_body]).to eq([200, { "detached" => 2 }])
    expect(Entry.where(id: own).pluck(:agent_id)).to eq([nil, nil])
    expect(Entry.find(foreign).agent_id).to eq(77)
    expect(own.map { |id| AuditEvent.where(company_id: company, entry_id: id).count }).to eq([1, 1])
    expect(own.map { |id| OutboxSnapshot.where(company_id: company, id:).pluck(:agent_id) }).to eq([[nil], [nil]])
    expect(AuditEvent.where(entry_id: foreign).count).to eq(0)

    # A replay of the same operation writes no second audit row.
    post "/v1/companies/#{company}/agents/77/detach-entries", params: body, headers: headers
    expect(response.parsed_body).to eq("detached" => 2)
    expect(AuditEvent.where(company_id: company).count).to eq(2)
    expect(OutboxSnapshot.where(company_id: company).count).to eq(2)
  end
end

RSpec.describe "Mark-billed transaction" do
  include_context "timekeeping entry writes"
  include_context "timekeeping entry writes without transactional fixtures"

  it "rolls back mark-billed with its audit rows when the outbox insert fails" do
    company = timekeeping_arrange.company
    billable = timekeeping_arrange.reserved_entry(company:, invoice_id: 501, state: "committed")
    service = timekeeping_arrange.service_identity(company:, name: "invoice-boundary",
                                                   operations: %w[prepare commit abort mark_billed detach_entries])
    allow(OutboxSnapshot).to receive(:insert_all!).and_raise(ActiveRecord::StatementInvalid, "outbox unavailable")
    expect(Entry.find(billable).bill_status).to eq("unbilled")

    # "Every reservation change that flips `locked`, every mark-billed and every detach writes an audit row and an
    # outbox snapshot row in the same transaction as the change."
    begin
      post "/v1/companies/#{company}/invoices/501/mark-billed",
           params: JSON.generate("operation_id" => SecureRandom.uuid, "generation" => timekeeping_arrange.current_generation),
           headers: { "Content-Type" => "application/json", "Authorization" => "Bearer #{service}" }
    rescue ActiveRecord::StatementInvalid
      nil
    end

    expect(OutboxSnapshot).to have_received(:insert_all!)
    expect(Entry.find(billable).bill_status).to eq("unbilled")
    expect(AuditEvent.where(company_id: company).count).to eq(0)
    expect(OutboxSnapshot.where(company_id: company).count).to eq(0)
    expect(ServiceIdempotencyReceipt.where(company_id: company).count).to eq(0)
  end
end

